import os
from pathlib import Path

import pytest


def read_note(name: str) -> str:
    """Return the text of the file `name` inside the directory `notes`.

    `name` is untrusted and is resolved relative to `notes` (relative to the
    working directory); subdirectories such as `sub/b.txt` are allowed. A
    missing, unreadable, or non-file target gives an empty string. Any name
    that would reach a file outside `notes` (via `..`, absolute paths,
    symlinks, NUL bytes, or any other spelling) also gives an empty string.
    """
    if not name or "\x00" in name or os.path.isabs(name) or name.startswith("/"):
        return ""
    try:
        base = Path("notes").resolve()
        target = (base / name).resolve()
        if target == base or not target.is_relative_to(base):
            return ""
        if not target.is_file():
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, ValueError, RuntimeError):
        return ""


@pytest.fixture
def workdir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / "notes"
    (notes / "sub" / "deep").mkdir(parents=True)
    (notes / "a.txt").write_text("alpha")
    (notes / "sub" / "b.txt").write_text("bravo")
    (notes / "sub" / "deep" / "c.txt").write_text("charlie")
    (notes / "empty.txt").write_text("")
    (tmp_path / "secret.txt").write_text("TOP SECRET")
    (tmp_path / "notes_evil").mkdir()
    (tmp_path / "notes_evil" / "x.txt").write_text("EVIL")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_top_level_file(workdir: Path) -> None:
    assert read_note("a.txt") == "alpha"


def test_reads_subdirectory_files(workdir: Path) -> None:
    assert read_note("sub/b.txt") == "bravo"
    assert read_note("sub/deep/c.txt") == "charlie"


def test_empty_file_gives_empty_string(workdir: Path) -> None:
    assert read_note("empty.txt") == ""


def test_missing_file(workdir: Path) -> None:
    assert read_note("nope.txt") == ""
    assert read_note("sub/nope.txt") == ""
    assert read_note("nodir/nope.txt") == ""


def test_empty_name_and_directories(workdir: Path) -> None:
    assert read_note("") == ""
    assert read_note(".") == ""
    assert read_note("sub") == ""
    assert read_note("sub/") == ""


def test_parent_traversal_blocked(workdir: Path) -> None:
    assert read_note("../secret.txt") == ""
    assert read_note("sub/../../secret.txt") == ""
    assert read_note("sub/deep/../../../secret.txt") == ""
    assert read_note("./../secret.txt") == ""
    assert read_note("..") == ""


def test_traversal_to_sibling_with_same_prefix(workdir: Path) -> None:
    assert read_note("../notes_evil/x.txt") == ""


def test_traversal_via_notes_name_blocked(workdir: Path) -> None:
    assert read_note("../notes/../secret.txt") == ""


def test_absolute_path_blocked(workdir: Path) -> None:
    assert read_note(str(workdir / "secret.txt")) == ""
    assert read_note("/etc/passwd") == ""
    assert read_note(str(workdir / "notes_evil" / "x.txt")) == ""


def test_double_slash_absolute_blocked(workdir: Path) -> None:
    assert read_note("//" + str(workdir / "secret.txt")) == ""


def test_nul_byte_gives_empty(workdir: Path) -> None:
    assert read_note("a.txt\x00../../secret.txt") == ""
    assert read_note("a\x00.txt") == ""


def test_symlink_file_escaping_notes_blocked(workdir: Path) -> None:
    link = workdir / "notes" / "link.txt"
    try:
        link.symlink_to(workdir / "secret.txt")
    except OSError:
        pytest.skip("symlinks unavailable")
    assert read_note("link.txt") == ""


def test_symlink_dir_escaping_notes_blocked(workdir: Path) -> None:
    link = workdir / "notes" / "out"
    try:
        link.symlink_to(workdir / "notes_evil", target_is_directory=True)
    except OSError:
        pytest.skip("symlinks unavailable")
    assert read_note("out/x.txt") == ""


def test_symlink_to_parent_dir_blocked(workdir: Path) -> None:
    link = workdir / "notes" / "up"
    try:
        link.symlink_to(workdir, target_is_directory=True)
    except OSError:
        pytest.skip("symlinks unavailable")
    assert read_note("up/secret.txt") == ""


@pytest.mark.skipif(
    not hasattr(os, "geteuid") or os.geteuid() == 0,
    reason="permission bits are not enforced for root",
)
def test_unreadable_file_gives_empty(workdir: Path) -> None:
    p = workdir / "notes" / "locked.txt"
    p.write_text("hidden")
    p.chmod(0)
    try:
        assert read_note("locked.txt") == ""
    finally:
        p.chmod(0o600)


def test_missing_notes_directory(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    assert read_note("a.txt") == ""

